Write {"file_path":"C:\Users\leigh\AppData\Local\Temp\ears_transform.js","content":"const fs = require('fs');
const path = require('path');

const BASE = 'D:/code/ESI.ts';

function classifyScenario(name) {
  const l = name.toLowerCase();
  if (/error|unavailable|unauthorized|forbidden|invalid|non-existent|not found|not exist|expired|rate limit|insufficient|unauthenticated|service down|server error|internal error|\.404|\.403|\.503|\.500|\.429|\.401/.test(l)) {
    return 'Unwanted';
  }
  if (/\bempty\b|\bno\b |with no |has no |is not |not in |zero |idle\b|disabled/.test(l) && !/error|unavail/.test(l)) {
    return 'State-driven';
  }
  if (/concurrent|performance|measure|benchmark|large|high.frequency|high concurrency|memory effic|monitor|response time/.test(l)) {
    return 'Ubiquitous';
  }
  if (/config|setting.*runtime|caching disabled|client works normally with caching/.test(l) && !/error/.test(l)) {
    return 'Optional';
  }
  return 'Event-driven';
}

function rewriteScenarioName(name, type) {
  const l = name.toLowerCase();

  if (type === 'Unwanted') {
    let condition = name.replace(/^Handle /, '').replace(/^Request /, 'requesting ');
    condition = condition.charAt(0).toLowerCase() + condition.slice(1);
    let response = 'handle it gracefully';
    if (/not found|non-existent|not exist|does not exist|404/.test(l)) response = 'return a not-found error';
    else if (/unauthorized|forbidden|403|insufficient perm|unauthenticated/.test(l)) response = 'return a forbidden error';
    else if (/rate limit|429/.test(l)) response = 'respect the rate limit';
    else if (/unavailable|503|service down|downtime/.test(l)) response = 'handle the service outage';
    else if (/server error|internal error|500/.test(l)) response = 'return a server error';
    else if (/authentication error|expired|401|invalid auth/.test(l)) response = 'return an authentication error';
    else if (/network/.test(l)) response = 'return a network error';
    return `IF ${condition}, THEN the client shall ${response}`;
  }

  if (type === 'State-driven') {
    let state = name.replace(/^Handle /, '').replace(/^Character /, 'the character ');
    state = state.charAt(0).toLowerCase() + state.slice(1);
    return `WHILE ${state}, the client shall return an empty result`;
  }

  if (type === 'Ubiquitous') {
    let behavior = name.charAt(0).toLowerCase() + name.slice(1);
    return `The client shall ${behavior}`;
  }

  if (type === 'Optional') {
    let feature = name.charAt(0).toLowerCase() + name.slice(1);
    return `WHERE ${feature}, the client shall behave accordingly`;
  }

  // Event-driven
  let action = name
    .replace(/^Get /, 'getting ')
    .replace(/^Retrieve /, 'retrieving ')
    .replace(/^List /, 'listing ')
    .replace(/^Create /, 'creating ')
    .replace(/^Delete /, 'deleting ')
    .replace(/^Update /, 'updating ')
    .replace(/^Send /, 'sending ')
    .replace(/^Accept /, 'accepting ')
    .replace(/^Decline /, 'declining ')
    .replace(/^Search /, 'searching ')
    .replace(/^Calculate /, 'calculating ')
    .replace(/^Filter /, 'filtering ')
    .replace(/^Complete /, 'completing ')
    .replace(/^Compare /, 'comparing ')
    .replace(/^Verify /, 'verifying ')
    .replace(/^Analyze /, 'analyzing ')
    .replace(/^Set /, 'setting ')
    .replace(/^Open /, 'opening ')
    .replace(/^Execute /, 'executing ')
    .replace(/^Chain /, 'chaining ')
    .replace(/^Add /, 'adding ')
    .replace(/^Remove /, 'removing ')
    .replace(/^Kick /, 'kicking ')
    .replace(/^Move /, 'moving ')
    .replace(/^Build /, 'building ')
    .replace(/^Identify /, 'identifying ')
    .replace(/^Cross-reference /, 'cross-referencing ')
    .replace(/^Paginate /, 'paginating ')
    .replace(/^Read /, 'reading ')
    .replace(/^Fetch /, 'fetching ')
    .replace(/^Full /, 'performing full ')
    .replace(/^Check /, 'checking ')
    .replace(/^Look up /, 'looking up ')
    .replace(/^Respond /, 'responding ')
    .replace(/^Mark /, 'marking ');

  if (action === name) {
    action = name.charAt(0).toLowerCase() + name.slice(1);
  }

  let result = 'respond';
  if (/^(getting|retrieving|listing|fetching|looking up)/.test(action)) result = 'return the data';
  else if (/^creating/.test(action)) result = 'create the resource';
  else if (/^(deleting|removing|kicking)/.test(action)) result = 'complete the operation';
  else if (/^updating/.test(action)) result = 'apply the changes';
  else if (/^(completing|performing)/.test(action)) result = 'complete all steps';
  else if (/^(searching)/.test(action)) result = 'return matching results';
  else if (/^(calculating)/.test(action)) result = 'return the result';
  else if (/^(setting|opening)/.test(action)) result = 'complete the operation';
  else if (/^(sending)/.test(action)) result = 'deliver the message';
  else if (/^(accepting|declining|responding)/.test(action)) result = 'record the response';
  else if (/^(analyzing|comparing|cross-referencing)/.test(action)) result = 'return the analysis';
  else if (/^(building)/.test(action)) result = 'produce the summary';
  else if (/^(adding)/.test(action)) result = 'add the entries';
  else if (/^(filtering)/.test(action)) result = 'return filtered results';
  else if (/^(chaining)/.test(action)) result = 'chain the operations';
  else if (/^(paginating)/.test(action)) result = 'return the correct page';
  else if (/^(verifying|checking)/.test(action)) result = 'validate the data';
  else if (/^(marking)/.test(action)) result = 'update the state';
  else if (/^(moving)/.test(action)) result = 'complete the move';

  return `WHEN ${action}, the client shall ${result}`;
}

// Step text replacements - applied to both .feature and .steps.ts
// Order matters: longest match first
const stepReplacements = [
  // When: "I <verb>" -> "the client <verb>s"
  ['When I retrieve', 'When the client retrieves'],
  ['When I request', 'When the client requests'],
  ['When I search', 'When the client searches'],
  ['When I fetch', 'When the client fetches'],
  ['When I gather', 'When the client gathers'],
  ['When I make', 'When the client makes'],
  ['When I check', 'When the client checks'],
  ['When I set', 'When the client sets'],
  ['When I open', 'When the client opens'],
  ['When I send', 'When the client sends'],
  ['When I delete', 'When the client deletes'],
  ['When I add', 'When the client adds'],
  ['When I create', 'When the client creates'],
  ['When I update', 'When the client updates'],
  ['When I attempt', 'When the client attempts'],
  ['When I perform', 'When the client performs'],
  ['When I analyze', 'When the client analyzes'],
  ['When I process', 'When the client processes'],
  ['When I access', 'When the client accesses'],
  ['When I accept', 'When the client accepts'],
  ['When I decline', 'When the client declines'],
  ['When I save', 'When the client saves'],
  ['When I kick', 'When the client kicks'],
  ['When I move', 'When the client moves'],
  ['When I clear', 'When the client clears'],
  ['When I examine', 'When the client examines'],
  ['When I inspect', 'When the client inspects'],
  ['When I optimize', 'When the client optimizes'],
  ['When I manage', 'When the client manages'],
  ['When I assemble', 'When the client assembles'],
  ['When I filter', 'When the client filters'],
  ['When I view', 'When the client views'],
  ['When I list', 'When the client lists'],
  ['When I respond', 'When the client responds'],
  ['When I call', 'When the client calls'],
  ['When I put', 'When the client puts'],

  // Then: "I should" -> "the client shall"
  ['Then I should be able to', 'Then the client shall'],
  ['Then I should successfully', 'Then the client shall successfully'],
  ['Then I should receive', 'Then the client shall return'],
  ['Then I should see', 'Then the client shall report'],
  ['Then I should have', 'Then the client shall have'],
  ['Then I should get', 'Then the client shall return'],
  ['Then I should find', 'Then the client shall return'],
  ['Then I should determine', 'Then the client shall determine'],
  ['Then I should build', 'Then the client shall build'],
  ['Then I should complete', 'Then the client shall complete'],
  ['Then I should handle', 'Then the client shall handle'],
  ['Then I should gather', 'Then the client shall gather'],
  ['Then I should access', 'Then the client shall access'],
  ['Then I should coordinate', 'Then the client shall coordinate'],
  ['Then I should minimize', 'Then the client shall minimize'],
  ['Then I can', 'Then the client shall'],
];

// "should" -> "shall" for Then lines with other subjects
const shouldToShall = [
  ['Then all should', 'Then all requests shall'],
  ['Then the response should', 'Then the response shall'],
  ['Then response should', 'Then the response shall'],
  ['Then the system should', 'Then the client shall'],
  ['Then the operation should', 'Then the operation shall'],
];

function applyStepReplacements(text) {
  let result = text;
  for (const [from, to] of stepReplacements) {
    result = result.split(from).join(to);
  }
  for (const [from, to] of shouldToShall) {
    result = result.split(from).join(to);
  }
  // Generic "should" -> "shall" in Then lines that still have "should"
  result = result.replace(/^(\s*Then .*)should\b/gm, '$1shall');
  // Also for step definitions: then(' ... should
  result = result.replace(/(then\(['"])(.*)should\b/g, (match, prefix, rest) => {
    return prefix + rest + 'shall';
  });
  return result;
}

function processFeatureFile(filePath) {
  let content = fs.readFileSync(filePath, 'utf8');
  const lines = content.split(/\r?\n/);
  const newLines = [];

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const scenarioMatch = line.match(/^(\s*)Scenario:\s*(.+)$/);

    if (scenarioMatch) {
      const indent = scenarioMatch[1];
      const oldName = scenarioMatch[2].trim();
      const type = classifyScenario(oldName);
      const newName = rewriteScenarioName(oldName, type);

      // Add EARS comment
      newLines.push(`${indent}# EARS: ${type}`);
      newLines.push(`${indent}Scenario: ${newName}`);
    } else {
      newLines.push(line);
    }
  }

  let result = newLines.join('\n');
  result = applyStepReplacements(result);

  // Normalize line endings to CRLF for Windows
  result = result.replace(/\r?\n/g, '\r\n');
  fs.writeFileSync(filePath, result, 'utf8');
  return content; // Return original for building replacement map
}

function buildReplacementMap(originalContent, newContent) {
  const map = {};

  // Extract scenario names
  const oldScenarios = [...originalContent.matchAll(/Scenario:\s*(.+)/g)].map(m => m[1].trim());
  const newScenarios = [...newContent.matchAll(/Scenario:\s*(.+)/g)].map(m => m[1].trim());

  for (let i = 0; i < oldScenarios.length && i < newScenarios.length; i++) {
    if (oldScenarios[i] !== newScenarios[i]) {
      map[oldScenarios[i]] = newScenarios[i];
    }
  }

  // Extract step text (Given/When/Then lines)
  const stepRegex = /^\s*(Given|When|Then)\s+(.+)$/gm;
  const oldSteps = [...originalContent.matchAll(stepRegex)].map(m => m[2].trim());
  const newSteps = [...newContent.matchAll(stepRegex)].map(m => m[2].trim());

  for (let i = 0; i < oldSteps.length && i < newSteps.length; i++) {
    if (oldSteps[i] !== newSteps[i]) {
      map[oldSteps[i]] = newSteps[i];
    }
  }

  return map;
}

function processStepsFile(stepsPath, replacementMap) {
  let content = fs.readFileSync(stepsPath, 'utf8');

  // Apply all replacements from the map
  for (const [oldStr, newStr] of Object.entries(replacementMap)) {
    // Replace in test() calls: test('old name', ...)
    content = content.split(oldStr).join(newStr);
  }

  // Normalize line endings
  content = content.replace(/\r?\n/g, '\r\n');
  fs.writeFileSync(stepsPath, content, 'utf8');
}

// Discover all feature/step pairs
const featureDirs = [
  path.join(BASE, 'tests/bdd/features/core'),
  path.join(BASE, 'tests/bdd/features/integration'),
  path.join(BASE, 'tests/bdd/features/performance'),
];

const stepDirs = [
  path.join(BASE, 'tests/bdd/step-definitions/core'),
  path.join(BASE, 'tests/bdd/step-definitions/integration'),
  path.join(BASE, 'tests/bdd/step-definitions/performance'),
];

let totalFeatures = 0;
let totalSteps = 0;

for (const featureDir of featureDirs) {
  if (!fs.existsSync(featureDir)) continue;
  const dirName = path.basename(featureDir);
  const stepsDir = stepDirs.find(d => d.endsWith(dirName));

  const featureFiles = fs.readdirSync(featureDir).filter(f => f.endsWith('.feature'));

  for (const featureFile of featureFiles) {
    const featurePath = path.join(featureDir, featureFile);
    const baseName = featureFile.replace('.feature', '');
    const stepsFile = `${baseName}.steps.ts`;
    const stepsPath = stepsDir ? path.join(stepsDir, stepsFile) : null;

    console.log(`Processing: ${featureFile}`);

    // Read original content
    const originalContent = fs.readFileSync(featurePath, 'utf8');

    // Process feature file
    processFeatureFile(featurePath);
    totalFeatures++;

    // Read new content to build replacement map
    const newContent = fs.readFileSync(featurePath, 'utf8');
    const replacementMap = buildReplacementMap(originalContent, newContent);

    // Process steps file if it exists
    if (stepsPath && fs.existsSync(stepsPath)) {
